#!/usr/bin/env bash
# Question 1: Service ${Q1_APP} unreachable. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: http }
            periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
spec:
  selector: { app: ${Q1_APP} }
  ports: [{ port: 80, targetPort: http }]
---
apiVersion: v1
kind: Pod
metadata:
  name: ${Q1_CLIENT}
  namespace: ${Q1_NS}
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
EOF
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}-admin
  namespace: ${Q1_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: ${Q1_APP}-admin }
  template:
    metadata:
      labels: { app: ${Q1_APP}-admin, tier: admin }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q1_APP}-admin
  namespace: ${Q1_NS}
spec:
  selector: { app: ${Q1_APP}-admin }
  ports: [{ port: 8080, targetPort: http }]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: ${Q1_APP}-admin-ingress
  namespace: ${Q1_NS}
spec:
  podSelector:
    matchLabels: { app: ${Q1_APP}-admin }
  policyTypes: [Ingress]
  ingress:
    - from: [{ podSelector: { matchLabels: { role: ops } } }]
      ports: [{ protocol: TCP, port: 80 }]
EOF
kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"
if ! kubectl -n "${Q1_NS}" wait --for=condition=Ready "pod/${Q1_CLIENT}" --timeout=180s; then
  kubectl -n "${Q1_NS}" describe "pod/${Q1_CLIENT}" >&2 || true
  exit 1
fi

case "${Q1_FAULT}" in
  manual-endpoints)
    cidr=$(grep -oE -- '--cluster-cidr=[0-9.]+' /etc/kubernetes/manifests/kube-controller-manager.yaml | cut -d= -f2)
    [[ -n "$cidr" ]] || { echo "could not read the Pod CIDR" >&2; exit 1; }
    prefix=$(echo "$cidr" | cut -d. -f1-2)
    kubectl -n "${Q1_NS}" patch service "${Q1_APP}" --type=json -p '[{"op":"remove","path":"/spec/selector"}]'
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"discovery.k8s.io/v1","kind":"EndpointSlice","metadata":{"name":"'"${Q1_APP}"'-manual","labels":{"kubernetes.io/service-name":"'"${Q1_APP}"'","endpointslice.kubernetes.io/managed-by":"ops-team"}},"addressType":"IPv4","ports":[{"name":"","port":80,"protocol":"TCP"}],"endpoints":[{"addresses":["'"$prefix"'.250.17"],"conditions":{"ready":true}},{"addresses":["'"$prefix"'.250.18"],"conditions":{"ready":true}}]}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q1_NS}" scale "deployment/${Q1_APP}" --replicas=2
# The question only makes sense if the client really is cut off: give the Pods time to start,
# then require several failed requests in a row.
sleep 20
for _ in $(seq 1 5); do
  if kubectl -n "${Q1_NS}" exec "${Q1_CLIENT}" -- wget -qO- -T 3 "http://${Q1_APP}" 2>/dev/null | grep -q nginx; then
    echo "the client can still reach the service" >&2
    exit 1
  fi
  sleep 2
done
